-- Athena saved query (Product_B2C_Intl)
-- ID: 2b662df5-2c32-4683-97ba-cc3f200c7a29
-- Name: GDS wise Toilet Coverage - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH route_flags AS ( SELECT route_id, MAX( CASE WHEN CONTAINS(persuasion_id,'537') THEN 1 ELSE 0 END ) AS toilet_route_id FROM user_interaction.search_route_details WHERE __time >= TIMESTAMP '2026-07-11 18:30:00' AND __time < TIMESTAMP '2026-07-19 18:30:00' GROUP BY 1 ), sl AS ( SELECT mri_session_id, route_id, MAX(op_id) AS operator_id, MAX(__time) AS sl_time FROM user_interaction.seat_layout_details WHERE __time >= TIMESTAMP '2026-07-11 18:30:00' AND __time < TIMESTAMP '2026-07-19 18:30:00' AND channel = 'MOBILE_APP' AND os = 'Android' AND src_id = 124 GROUP BY 1,2 ), coverage AS ( SELECT DATE(DATE_ADD('MINUTE',330,u.__time)) AS doi, sl.operator_id, u.event_src, MAX(COALESCE(rf.toilet_route_id,0)) AS toilet_route_id, COUNT(DISTINCT CASE WHEN u.event_group='sl_screen_load' THEN u.mri_session_id END) AS sl_load_sessions, COUNT(DISTINCT CASE WHEN u.event_group='sl_click_info' AND u.event_name='ToiletShown' THEN u.mri_session_id END) AS toilet_shown_sessions FROM user_interaction.ui_ux_events u JOIN sl ON sl.mri_session_id=u.mri_session_id AND sl.sl_time BETWEEN u.__time-INTERVAL '1' SECOND AND u.__time+INTERVAL '1' SECOND LEFT JOIN route_flags rf ON rf.route_id=sl.route_id WHERE u.__time >= TIMESTAMP '2026-07-11 18:30:00' AND u.__time < TIMESTAMP '2026-07-19 18:30:00' AND u.header_bu='BUS' AND u.header_country='IND' AND ( (UPPER(u.event_src)='ANDROID' AND u.app_code>=821000) OR (UPPER(u.event_src)='IOS' AND u.app_code>=862200) ) GROUP BY 1,2,3 HAVING COUNT(DISTINCT CASE WHEN u.event_group='sl_screen_load' THEN u.mri_session_id END)>0 ) SELECT c.operator_id, op.travels_full_name, CASE WHEN regexp_like(TRIM(v.assembly_name), '(?i)^RedBus\.Vendor\.') THEN regexp_extract(TRIM(v.assembly_name), '(?i)^RedBus\.Vendor\.(.+)$', 1) ELSE TRIM(v.assembly_name) END AS gds_name, MAX(c.toilet_route_id) AS toilet_operator_id, SUM(c.sl_load_sessions) AS sl_load_sessions, SUM(c.toilet_shown_sessions) AS toilet_shown_sessions FROM coverage c LEFT JOIN lis.operators op ON op.operator_id=c.operator_id LEFT JOIN lis.vendor v ON v.id=op.operator_id GROUP BY 1,2,3 ORDER BY 4 DESC, 5 DESC;
